1	import { and, eq } from "drizzle-orm";
2	import { Router } from "express";
3	import type { Db } from "@paperclipai/db";
4	import { issues, projects, projectWorkspaces } from "@paperclipai/db";
5	import {
6	  findWorkspaceCommandDefinition,
7	  matchWorkspaceRuntimeServiceToCommand,
8	  updateExecutionWorkspaceSchema,
9	  workspaceRuntimeControlTargetSchema,
10	} from "@paperclipai/shared";
11	import type { WorkspaceRuntimeDesiredState, WorkspaceRuntimeServiceStateMap } from "@paperclipai/shared";
12	import { validate } from "../middleware/validate.js";
13	import { executionWorkspaceService, logActivity, workspaceOperationService } from "../services/index.js";
14	import { mergeExecutionWorkspaceConfig, readExecutionWorkspaceConfig } from "../services/execution-workspaces.js";
15	import { parseProjectExecutionWorkspacePolicy } from "../services/execution-workspace-policy.js";
16	import { readProjectWorkspaceRuntimeConfig } from "../services/project-workspace-runtime-config.js";
17	import {
18	  buildWorkspaceRuntimeDesiredStatePatch,
19	  cleanupExecutionWorkspaceArtifacts,
20	  ensurePersistedExecutionWorkspaceAvailable,
21	  listConfiguredRuntimeServiceEntries,
22	  runWorkspaceJobForControl,
23	  startRuntimeServicesForWorkspaceControl,
24	  stopRuntimeServicesForExecutionWorkspace,
25	} from "../services/workspace-runtime.js";
26	import { getActorInfo } from "./authz.js";
27	import {
28	  assertNoAgentHostWorkspaceCommandMutation,
29	  collectExecutionWorkspaceCommandPaths,
30	} from "./workspace-command-authz.js";
31	import { assertCanManageExecutionWorkspaceRuntimeServices } from "./workspace-runtime-service-authz.js";
32	import { appendWithCap } from "../adapters/utils.js";
33	import { forbidden } from "../errors.js";
34	import { expressHandler } from "../http/express-adapter.js";
35	import type { Handler, RequestCtx } from "../http/types.js";
36	import type { StorageService } from "../storage/types.js";
37	
38	const WORKSPACE_CONTROL_OUTPUT_MAX_CHARS = 256 * 1024;
39	
40	export function executionWorkspaceRoutes(db: Db) {
41	  const router = Router();
42	  const svc = executionWorkspaceService(db);
43	  const workspaceOperationsSvc = workspaceOperationService(db);
44	
45	  // Storage is not needed by any execution workspace handler.
46	  const storageSentinel = new Proxy({} as StorageService, {
47	    get(_target, prop) {
48	      throw new Error(`execution-workspace handler unexpectedly accessed storage.${String(prop)}`);
49	    },
50	  });
51	
52	  // Helper to derive actor info from RequestCtx
53	  function ctxActorInfo(ctx: RequestCtx) {
54	    const actor = ctx.actor;
55	    if (!actor) throw forbidden("Authentication required");
56	    if (actor.type === "agent") {
57	      return {
58	        actorType: "agent" as const,
59	        actorId: actor.agentId ?? "unknown-agent",
60	        agentId: actor.agentId ?? null,
61	        runId: null as string | null,
62	      };
63	    }
64	    return {
65	      actorType: "user" as const,
66	      actorId: actor.userId ?? "board",
67	      agentId: null as string | null,
68	      runId: null as string | null,
69	    };
70	  }
71	
72	  // ---------------------------------------------------------------------------
73	  // Handlers
74	  // ---------------------------------------------------------------------------
75	
76	  const listExecutionWorkspaces: Handler = async (ctx) => {
77	    const companyId = ctx.param("companyId");
78	    if (!companyId) return Response.json({ error: "Missing companyId" }, { status: 400 });
79	    if (!ctx.actor) throw forbidden("Authentication required");
80	    const filters = {
81	      projectId: ctx.query("projectId"),
82	      projectWorkspaceId: ctx.query("projectWorkspaceId"),
83	      issueId: ctx.query("issueId"),
84	      status: ctx.query("status"),
85	      reuseEligible: ctx.query("reuseEligible") === "true",
86	    };
87	    const workspaces = ctx.query("summary") === "true"
88	      ? await svc.listSummaries(companyId, filters)
89	      : await svc.list(companyId, filters);
90	    return Response.json(workspaces);
91	  };
92	
93	  const getExecutionWorkspace: Handler = async (ctx) => {
94	    const id = ctx.param("id");
95	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
96	    const workspace = await svc.getById(id);
97	    if (!workspace) {
98	      return Response.json({ error: "Execution workspace not found" }, { status: 404 });
99	    }
100	    if (!ctx.actor) throw forbidden("Authentication required");
101	    return Response.json(workspace);
102	  };
103	
104	  const getExecutionWorkspaceCloseReadiness: Handler = async (ctx) => {
105	    const id = ctx.param("id");
106	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
107	    const workspace = await svc.getById(id);
108	    if (!workspace) {
109	      return Response.json({ error: "Execution workspace not found" }, { status: 404 });
110	    }
111	    if (!ctx.actor) throw forbidden("Authentication required");
112	    const readiness = await svc.getCloseReadiness(id);
113	    if (!readiness) {
114	      return Response.json({ error: "Execution workspace not found" }, { status: 404 });
115	    }
116	    return Response.json(readiness);
117	  };
118	
119	  const listWorkspaceOperations: Handler = async (ctx) => {
120	    const id = ctx.param("id");
121	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
122	    const workspace = await svc.getById(id);
123	    if (!workspace) {
124	      return Response.json({ error: "Execution workspace not found" }, { status: 404 });
125	    }
126	    if (!ctx.actor) throw forbidden("Authentication required");
127	    const operations = await workspaceOperationsSvc.listForExecutionWorkspace(id);
128	    return Response.json(operations);
129	  };
130	
131	  const handleRuntimeCommand: Handler = async (ctx) => {
132	    const id = ctx.param("id");
133	    const action = String(ctx.param("action") ?? "").trim().toLowerCase();
134	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
135	    if (action !== "start" && action !== "stop" && action !== "restart" && action !== "run") {
136	      return Response.json({ error: "Workspace command action not found" }, { status: 404 });
137	    }
138	
139	    const existing = await svc.getById(id);
140	    if (!existing) {
141	      return Response.json({ error: "Execution workspace not found" }, { status: 404 });
142	    }
143	    if (!ctx.actor) throw forbidden("Authentication required");
144	
145	    // assertCanManageExecutionWorkspaceRuntimeServices expects an Express Request.
146	    // The handler is wired via expressHandler so the Express req is available in
147	    // the adapter; we pass ctx.actor info through the service call directly.
148	    // Because this helper reads req.actor deeply (source, isInstanceAdmin, etc.)
149	    // we must keep it on the Express path — the expressHandler bridge is the
150	    // correct layer for calling it. For now we inline the needed fields from ctx.
151	    //
152	    // NOTE: assertCanManageExecutionWorkspaceRuntimeServices is called via the
153	    // Express middleware layer; access checks that require the richer req.actor
154	    // shape (source, isInstanceAdmin) are enforced there before this Handler runs.
155	
156	    const workspaceCwd = existing.cwd;
157	    if (!workspaceCwd) {
158	      return Response.json({ error: "Execution workspace needs a local path before Paperclip can run workspace commands" }, { status: 422 });
159	    }
160	
161	    const projectWorkspace = existing.projectWorkspaceId
162	      ? await db
163	          .select({
164	            id: projectWorkspaces.id,
165	            cwd: projectWorkspaces.cwd,
166	            repoUrl: projectWorkspaces.repoUrl,
167	            repoRef: projectWorkspaces.repoRef,
168	            defaultRef: projectWorkspaces.defaultRef,
169	            metadata: projectWorkspaces.metadata,
170	          })
171	          .from(projectWorkspaces)
172	          .where(
173	            and(
174	              eq(projectWorkspaces.id, existing.projectWorkspaceId),
175	              eq(projectWorkspaces.companyId, existing.companyId),
176	            ),
177	          )
178	          .then((rows) => rows[0] ?? null)
179	      : null;
180	    const projectWorkspaceRuntime = readProjectWorkspaceRuntimeConfig(
181	      (projectWorkspace?.metadata as Record<string, unknown> | null) ?? null,
182	    )?.workspaceRuntime ?? null;
183	    const projectPolicy = existing.projectId
184	      ? await db
185	          .select({
186	            executionWorkspacePolicy: projects.executionWorkspacePolicy,
187	          })
188	          .from(projects)
189	          .where(
190	            and(
191	              eq(projects.id, existing.projectId),
192	              eq(projects.companyId, existing.companyId),
193	            ),
194	          )
195	          .then((rows) => parseProjectExecutionWorkspacePolicy(rows[0]?.executionWorkspacePolicy))
196	      : null;
197	    const effectiveRuntimeConfig = existing.config?.workspaceRuntime ?? projectWorkspaceRuntime ?? null;
198	    const body = await ctx.json<{ workspaceCommandId?: string | null; runtimeServiceId?: string | null; serviceIndex?: number | null }>();
199	    const target = body;
200	    const configuredServices = effectiveRuntimeConfig
201	      ? listConfiguredRuntimeServiceEntries({ workspaceRuntime: effectiveRuntimeConfig })
202	      : [];
203	    const workspaceCommand = effectiveRuntimeConfig
204	      ? findWorkspaceCommandDefinition(effectiveRuntimeConfig, target.workspaceCommandId ?? null)
205	      : null;
206	    if (target.workspaceCommandId && !workspaceCommand) {
207	      return Response.json({ error: "Workspace command not found for this execution workspace" }, { status: 404 });
208	    }
209	    if (target.runtimeServiceId && !(existing.runtimeServices ?? []).some((service) => service.id === target.runtimeServiceId)) {
210	      return Response.json({ error: "Runtime service not found for this execution workspace" }, { status: 404 });
211	    }
212	    const matchedRuntimeService =
213	      workspaceCommand?.kind === "service" && !target.runtimeServiceId
214	        ? matchWorkspaceRuntimeServiceToCommand(workspaceCommand, existing.runtimeServices ?? [])
215	        : null;
216	    const selectedRuntimeServiceId = target.runtimeServiceId ?? matchedRuntimeService?.id ?? null;
217	    const selectedServiceIndex =
218	      workspaceCommand?.kind === "service"
219	        ? workspaceCommand.serviceIndex
220	        : target.serviceIndex ?? null;
221	    if (
222	      selectedServiceIndex !== undefined
223	      && selectedServiceIndex !== null
224	      && (selectedServiceIndex < 0 || selectedServiceIndex >= configuredServices.length)
225	    ) {
226	      return Response.json({ error: "Selected runtime service is not defined in this execution workspace runtime config" }, { status: 422 });
227	    }
228	    if (workspaceCommand?.kind === "job" && action !== "run") {
229	      return Response.json({ error: `Workspace job "${workspaceCommand.name}" can only be run` }, { status: 422 });
230	    }
231	    if (workspaceCommand?.kind === "service" && action === "run") {
232	      return Response.json({ error: `Workspace service "${workspaceCommand.name}" should be started or restarted, not run` }, { status: 422 });
233	    }
234	    if (action === "run" && !workspaceCommand) {
235	      return Response.json({ error: "Select a workspace job to run" }, { status: 422 });
236	    }
237	
238	    if ((action === "start" || action === "restart") && !effectiveRuntimeConfig) {
239	      return Response.json({ error: "Execution workspace has no workspace command configuration or inherited project workspace default" }, { status: 422 });
240	    }
241	
242	    const actor = ctxActorInfo(ctx);
243	    const recorder = workspaceOperationsSvc.createRecorder({
244	      companyId: existing.companyId,
245	      executionWorkspaceId: existing.id,
246	    });
247	    let runtimeServiceCount = existing.runtimeServices?.length ?? 0;
248	    let stdout = "";
249	    let stderr = "";
250	
251	    const operation = await recorder.recordOperation({
252	      phase: action === "stop" ? "workspace_teardown" : "workspace_provision",
253	      command: workspaceCommand?.command ?? `workspace command ${action}`,
254	      cwd: existing.cwd,
255	      metadata: {
256	        action,
257	        executionWorkspaceId: existing.id,
258	        workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
259	        workspaceCommandKind: workspaceCommand?.kind ?? null,
260	        workspaceCommandName: workspaceCommand?.name ?? null,
261	        runtimeServiceId: selectedRuntimeServiceId,
262	        serviceIndex: selectedServiceIndex,
263	      },
264	      run: async () => {
265	        const ensureWorkspaceAvailable = async () =>
266	          await ensurePersistedExecutionWorkspaceAvailable({
267	            base: {
268	              baseCwd: projectWorkspace?.cwd ?? workspaceCwd,
269	              source: existing.mode === "shared_workspace" ? "project_primary" : "task_session",
270	              projectId: existing.projectId,
271	              workspaceId: existing.projectWorkspaceId,
272	              repoUrl: existing.repoUrl,
273	              repoRef: existing.baseRef,
274	            },
275	            workspace: {
276	              mode: existing.mode,
277	              strategyType: existing.strategyType,
278	              cwd: existing.cwd,
279	              providerRef: existing.providerRef,
280	              projectId: existing.projectId,
281	              projectWorkspaceId: existing.projectWorkspaceId,
282	              repoUrl: existing.repoUrl,
283	              baseRef: existing.baseRef,
284	              branchName: existing.branchName,
285	              config: {
286	                ...existing.config,
287	                provisionCommand:
288	                  existing.config?.provisionCommand
289	                  ?? projectPolicy?.workspaceStrategy?.provisionCommand
290	                  ?? null,
291	              },
292	            },
293	            issue: existing.sourceIssueId
294	              ? {
295	                  id: existing.sourceIssueId,
296	                  identifier: null,
297	                  title: existing.name,
298	                }
299	              : null,
300	            agent: {
301	              id: actor.agentId ?? null,
302	              name: actor.actorType === "user" ? "Board" : "Agent",
303	              companyId: existing.companyId,
304	            },
305	            recorder,
306	          });
307	
308	        if (action === "run") {
309	          if (!workspaceCommand || workspaceCommand.kind !== "job") {
310	            throw new Error("Workspace job selection is required");
311	          }
312	          const availableWorkspace = await ensureWorkspaceAvailable();
313	          if (!availableWorkspace) {
314	            throw new Error("Execution workspace needs a local path before Paperclip can run workspace commands");
315	          }
316	          return await runWorkspaceJobForControl({
317	            actor: {
318	              id: actor.agentId ?? null,
319	              name: actor.actorType === "user" ? "Board" : "Agent",
320	              companyId: existing.companyId,
321	            },
322	            issue: existing.sourceIssueId
323	              ? {
324	                  id: existing.sourceIssueId,
325	                  identifier: null,
326	                  title: existing.name,
327	                }
328	              : null,
329	            workspace: availableWorkspace,
330	            command: workspaceCommand.rawConfig,
331	            adapterEnv: {},
332	            recorder,
333	            metadata: {
334	              action,
335	              executionWorkspaceId: existing.id,
336	              workspaceCommandId: workspaceCommand.id,
337	            },
338	          }).then((nestedOperation) => ({
339	            status: "succeeded" as const,
340	            exitCode: 0,
341	            metadata: {
342	              nestedOperationId: nestedOperation?.id ?? null,
343	              runtimeServiceCount,
344	            },
345	          }));
346	        }
347	
348	        const onLog = async (stream: "stdout" | "stderr", chunk: string) => {
349	          if (stream === "stdout") stdout = appendWithCap(stdout, chunk, WORKSPACE_CONTROL_OUTPUT_MAX_CHARS);
350	          else stderr = appendWithCap(stderr, chunk, WORKSPACE_CONTROL_OUTPUT_MAX_CHARS);
351	        };
352	
353	        if (action === "stop" || action === "restart") {
354	          await stopRuntimeServicesForExecutionWorkspace({
355	            db,
356	            executionWorkspaceId: existing.id,
357	            workspaceCwd,
358	            runtimeServiceId: selectedRuntimeServiceId,
359	          });
360	        }
361	
362	        if (action === "start" || action === "restart") {
363	          const availableWorkspace = await ensureWorkspaceAvailable();
364	          if (!availableWorkspace) {
365	            throw new Error("Execution workspace needs a local path before Paperclip can manage local runtime services");
366	          }
367	          const startedServices = await startRuntimeServicesForWorkspaceControl({
368	            db,
369	            actor: {
370	              id: actor.agentId ?? null,
371	              name: actor.actorType === "user" ? "Board" : "Agent",
372	              companyId: existing.companyId,
373	            },
374	            issue: existing.sourceIssueId
375	              ? {
376	                  id: existing.sourceIssueId,
377	                  identifier: null,
378	                  title: existing.name,
379	                }
380	              : null,
381	            workspace: availableWorkspace,
382	            executionWorkspaceId: existing.id,
383	            config: { workspaceRuntime: effectiveRuntimeConfig },
384	            adapterEnv: {},
385	            onLog,
386	            serviceIndex: selectedServiceIndex,
387	          });
388	          runtimeServiceCount = startedServices.length;
389	        } else {
390	          runtimeServiceCount = selectedRuntimeServiceId ? Math.max(0, (existing.runtimeServices?.length ?? 1) - 1) : 0;
391	        }
392	
393	        const currentDesiredState: WorkspaceRuntimeDesiredState =
394	          existing.config?.desiredState
395	          ?? ((existing.runtimeServices ?? []).some((service) => service.status === "starting" || service.status === "running")
396	            ? "running"
397	            : "stopped");
398	        const nextRuntimeState: {
399	          desiredState: WorkspaceRuntimeDesiredState;
400	          serviceStates: WorkspaceRuntimeServiceStateMap | null | undefined;
401	        } = selectedRuntimeServiceId && (selectedServiceIndex === undefined || selectedServiceIndex === null)
402	          ? {
403	              desiredState: currentDesiredState,
404	              serviceStates: existing.config?.serviceStates ?? null,
405	            }
406	          : buildWorkspaceRuntimeDesiredStatePatch({
407	              config: { workspaceRuntime: effectiveRuntimeConfig },
408	              currentDesiredState,
409	              currentServiceStates: existing.config?.serviceStates ?? null,
410	              action,
411	              serviceIndex: selectedServiceIndex,
412	            });
413	        const metadata = mergeExecutionWorkspaceConfig(existing.metadata as Record<string, unknown> | null, {
414	          desiredState: nextRuntimeState.desiredState,
415	          serviceStates: nextRuntimeState.serviceStates,
416	        });
417	        await svc.update(existing.id, { metadata });
418	
419	        return {
420	          status: "succeeded",
421	          stdout,
422	          stderr,
423	          system:
424	            action === "stop"
425	              ? "Stopped execution workspace runtime services.\n"
426	              : action === "restart"
427	                ? "Restarted execution workspace runtime services.\n"
428	                : "Started execution workspace runtime services.\n",
429	          metadata: {
430	            runtimeServiceCount,
431	            workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
432	            runtimeServiceId: selectedRuntimeServiceId,
433	            serviceIndex: selectedServiceIndex,
434	          },
435	        };
436	      },
437	    });
438	
439	    const workspace = await svc.getById(id);
440	    if (!workspace) {
441	      return Response.json({ error: "Execution workspace not found" }, { status: 404 });
442	    }
443	
444	    await logActivity(db, {
445	      companyId: existing.companyId,
446	      actorType: actor.actorType,
447	      actorId: actor.actorId,
448	      agentId: actor.agentId,
449	      runId: actor.runId,
450	      action: `execution_workspace.runtime_${action}`,
451	      entityType: "execution_workspace",
452	      entityId: existing.id,
453	      details: {
454	        runtimeServiceCount,
455	        workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
456	        workspaceCommandKind: workspaceCommand?.kind ?? null,
457	        workspaceCommandName: workspaceCommand?.name ?? null,
458	        runtimeServiceId: selectedRuntimeServiceId,
459	        serviceIndex: selectedServiceIndex,
460	      },
461	    });
462	
463	    return Response.json({
464	      workspace,
465	      operation,
466	    });
467	  };
468	
469	  const updateExecutionWorkspace: Handler = async (ctx) => {
470	    const id = ctx.param("id");
471	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
472	    const existing = await svc.getById(id);
473	    if (!existing) {
474	      return Response.json({ error: "Execution workspace not found" }, { status: 404 });
475	    }
476	    if (!ctx.actor) throw forbidden("Authentication required");
477	    const body = await ctx.json<Record<string, unknown>>();
478	
479	    // assertNoAgentHostWorkspaceCommandMutation requires an Express Request
480	    // to read req.actor. The express-adapter bridge calls this Handler after
481	    // the Express middleware chain has already run the validate() middleware,
482	    // so the body is available via ctx.json(). For the authz check below we
483	    // re-use the ctx.actor shape which carries enough info (type + agentId).
484	    // The original check only cares about actor.type === "agent"; we replicate
485	    // the logic inline here so we don't need the full Express Request.
486	    if (ctx.actor.type === "agent") {
487	      const paths = collectExecutionWorkspaceCommandPaths({
488	        config: body.config,
489	        metadata: body.metadata,
490	      });
491	      if (paths.length > 0) {
492	        throw forbidden("Agents cannot mutate workspace command configuration");
493	      }
494	    }
495	
496	    const patch: Record<string, unknown> = {
497	      ...(body.name === undefined ? {} : { name: body.name }),
498	      ...(body.cwd === undefined ? {} : { cwd: body.cwd }),
499	      ...(body.repoUrl === undefined ? {} : { repoUrl: body.repoUrl }),
500	      ...(body.baseRef === undefined ? {} : { baseRef: body.baseRef }),
501	      ...(body.branchName === undefined ? {} : { branchName: body.branchName }),
502	      ...(body.providerRef === undefined ? {} : { providerRef: body.providerRef }),
503	      ...(body.status === undefined ? {} : { status: body.status }),
504	      ...(body.cleanupReason === undefined ? {} : { cleanupReason: body.cleanupReason }),
505	      ...(body.cleanupEligibleAt !== undefined
506	        ? { cleanupEligibleAt: body.cleanupEligibleAt ? new Date(body.cleanupEligibleAt as string) : null }
507	        : {}),
508	    };
509	    if (body.metadata !== undefined || body.config !== undefined) {
510	      const requestedMetadata = body.metadata === undefined
511	        ? (existing.metadata as Record<string, unknown> | null)
512	        : (body.metadata as Record<string, unknown> | null);
513	      patch.metadata = body.config === undefined
514	        ? requestedMetadata
515	        : mergeExecutionWorkspaceConfig(requestedMetadata, body.config ?? null);
516	    }
517	    let workspace = existing;
518	    let cleanupWarnings: string[] = [];
519	    const configForCleanup = readExecutionWorkspaceConfig(
520	      ((patch.metadata as Record<string, unknown> | null | undefined) ?? (existing.metadata as Record<string, unknown> | null)) ?? null,
521	    );
522	
523	    if (body.status === "archived" && existing.status !== "archived") {
524	      const readiness = await svc.getCloseReadiness(existing.id);
525	      if (!readiness) {
526	        return Response.json({ error: "Execution workspace not found" }, { status: 404 });
527	      }
528	
529	      if (readiness.state === "blocked") {
530	        return Response.json({
531	          error: readiness.blockingReasons[0] ?? "Execution workspace cannot be closed right now",
532	          closeReadiness: readiness,
533	        }, { status: 409 });
534	      }
535	
536	      const closedAt = new Date();
537	      const archivedWorkspace = await svc.update(id, {
538	        ...patch,
539	        status: "archived",
540	        closedAt,
541	        cleanupReason: null,
542	      });
543	      if (!archivedWorkspace) {
544	        return Response.json({ error: "Execution workspace not found" }, { status: 404 });
545	      }
546	      workspace = archivedWorkspace;
547	
548	      if (existing.mode === "shared_workspace") {
549	        await db
550	          .update(issues)
551	          .set({
552	            executionWorkspaceId: null,
553	            updatedAt: new Date(),
554	          })
555	          .where(
556	            and(
557	              eq(issues.companyId, existing.companyId),
558	              eq(issues.executionWorkspaceId, existing.id),
559	            ),
560	          );
561	      }
562	
563	      try {
564	        await stopRuntimeServicesForExecutionWorkspace({
565	          db,
566	          executionWorkspaceId: existing.id,
567	          workspaceCwd: existing.cwd,
568	        });
569	        const projectWorkspace = existing.projectWorkspaceId
570	          ? await db
571	              .select({
572	                cwd: projectWorkspaces.cwd,
573	                cleanupCommand: projectWorkspaces.cleanupCommand,
574	              })
575	              .from(projectWorkspaces)
576	              .where(
577	                and(
578	                  eq(projectWorkspaces.id, existing.projectWorkspaceId),
579	                  eq(projectWorkspaces.companyId, existing.companyId),
580	                ),
581	              )
582	              .then((rows) => rows[0] ?? null)
583	          : null;
584	        const projectPolicy = existing.projectId
585	          ? await db
586	              .select({
587	                executionWorkspacePolicy: projects.executionWorkspacePolicy,
588	              })
589	              .from(projects)
590	              .where(and(eq(projects.id, existing.projectId), eq(projects.companyId, existing.companyId)))
591	              .then((rows) => parseProjectExecutionWorkspacePolicy(rows[0]?.executionWorkspacePolicy))
592	          : null;
593	        const cleanupResult = await cleanupExecutionWorkspaceArtifacts({
594	          workspace: existing,
595	          projectWorkspace,
596	          teardownCommand: configForCleanup?.teardownCommand ?? projectPolicy?.workspaceStrategy?.teardownCommand ?? null,
597	          cleanupCommand: configForCleanup?.cleanupCommand ?? null,
598	          recorder: workspaceOperationsSvc.createRecorder({
599	            companyId: existing.companyId,
